Here you go — clean, simple, exam-ready stack code using **array** in C:

---

### ✅ Stack using Array (Push, Pop, isEmpty, isFull)

```c
#include <stdio.h>
#define MAX 5

int stack[MAX];
int top = -1;

// Check if stack is full
int isFull() {
    return top == MAX - 1;
}

// Check if stack is empty
int isEmpty() {
    return top == -1;
}

// Push element into stack
void push(int x) {
    if (isFull()) {
        printf("Stack Overflow! Cannot push %d\n", x);
    } else {
        stack[++top] = x;
        printf("%d pushed into stack\n", x);
    }
}

// Pop element from stack
int pop() {
    if (isEmpty()) {
        printf("Stack Underflow! Nothing to pop\n");
        return -1;
    } else {
        return stack[top--];
    }
}

// Display stack
void display() {
    if (isEmpty()) {
        printf("Stack is empty\n");
    } else {
        printf("Stack elements: ");
        for (int i = top; i >= 0; i--) {
            printf("%d ", stack[i]);
        }
        printf("\n");
    }
}

int main() {
    push(10);
    push(20);
    push(30);
    display();

    printf("Popped: %d\n", pop());
    display();

    return 0;
}
```

---

### 📌 Key Notes for Exam
- `top = -1` means **stack empty**
- When `top == MAX-1` → **stack full**
- **Push:** `++top` then store element  
- **Pop:** return `stack[top--]`

