## ✅ Stack Using Singly Linked List in C  
( push, pop, peek, isEmpty )

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* top = NULL;

// Check if stack is empty
int isEmpty() {
    return top == NULL;
}

// Push element
void push(int x) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        printf("Memory allocation failed!\n");
        return;
    }

    newNode->data = x;
    newNode->next = top;
    top = newNode;

    printf("%d pushed to stack\n", x);
}

// Pop element
int pop() {
    if (isEmpty()) {
        printf("Stack Underflow! Nothing to pop\n");
        return -1;
    }

    struct Node* temp = top;
    int popped = temp->data;

    top = top->next;
    free(temp);

    return popped;
}

// Peek element
int peek() {
    if (isEmpty()) {
        printf("Stack is empty\n");
        return -1;
    }
    return top->data;
}

// Display stack
void display() {
    if (isEmpty()) {
        printf("Stack is empty\n");
        return;
    }

    struct Node* temp = top;
    printf("Stack elements: ");
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    push(10);
    push(20);
    push(30);
    display();

    printf("Top element: %d\n", peek());

    printf("Popped: %d\n", pop());
    display();

    return 0;
}
```

---

### 📝 Short Theory for Viva
- **Linked list stack grows dynamically** — no limit like array
- Operations work on **head** of list
- **Push:** insert at beginning  
- **Pop:** delete from beginning  
- **Time complexity:** `O(1)` for push & pop

